import{_ as g,C as c,o as n,c as u,j as d,a,G as t,a3 as o,b as s,w as i,a9 as l}from"./chunks/framework.exbasbhr.js";const E=JSON.parse('{"title":"System Architecture Design","description":"System Architecture Design","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"System Architecture Design","description":"System Architecture Design"},"headers":[],"relativePath":"en/dev/system-architecture/index.md","filePath":"en/dev/system-architecture/index.md"}'),m={name:"en/dev/system-architecture/index.md"};function h(y,e,A,f,b,v){const p=c("ArticleMetadata"),r=c("Mermaid");return n(),u("div",null,[e[4]||(e[4]=d("h1",{id:"system-architecture-design",tabindex:"-1"},[a("System Architecture Design "),d("a",{class:"header-anchor",href:"#system-architecture-design","aria-label":'Permalink to "System Architecture Design"'},"​")],-1)),t(p),e[5]||(e[5]=o('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document focuses on the system architecture design of InkCanvasForClass, providing a comprehensive explanation of the MVVM architectural pattern, modular and layered design, application entry and startup workflows, global services and event-driven mechanisms, configuration management, and monitoring &amp; diagnostics. It is intended to help developers and maintainers quickly understand the system&#39;s design philosophy, key implementations, and extension points.</p><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>InkCanvasForClass adopts the WPF desktop application architecture combined with a modular and layered design to decouple UI, business logic, auxiliary services, and the plugin ecosystem. An overview of the core directories and their responsibilities is as follows:</p><ul><li>Ink Canvas: Main application project, containing UI, main window, toolbars, pop-up windows, settings views, internationalization resources, styles, and icon resources.</li><li>Helpers: General services and infrastructure, such as logging, exception handling, configuration file management, telemetry, notification center, global hotkeys, PPT/COM helpers, etc.</li><li>Controls: Reusable UI controls and toolbar systems, supporting dynamic layouts and rule-based rendering.</li><li>Windows: Various windows and settings pages containing specific functional views.</li><li>InkCanvas.PluginSdk: Plugin interfaces and host contracts, defining plugin lifecycles and service registration capabilities.</li><li>Configuration &amp; Resources: App.config, App.xaml, resource dictionaries, localized strings, etc.</li></ul>',5)),(n(),s(l,null,{default:i(()=>[t(r,{id:"mermaid-47",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Application%20Layer%22%0AApp%5B%22App.xaml.cs%3Cbr%2F%3EApplication%20Entry%20and%20Global%20Events%22%5D%0AMainWindow%5B%22MainWindow.xaml.cs%3Cbr%2F%3EMain%20Window%20and%20View%20Models%22%5D%0Aend%0Asubgraph%20%22Service%20Layer%22%0ALog%5B%22LogHelper.cs%3Cbr%2F%3ELogging%20Service%22%5D%0AExHandler%5B%22ExceptionHandler.cs%3Cbr%2F%3EException%20Handling%22%5D%0ANoti%5B%22NotificationCenterService.cs%3Cbr%2F%3ENotification%20Center%22%5D%0ATelemetry%5B%22TelemetryUploader.cs%3Cbr%2F%3ETelemetry%20Upload%22%5D%0AHotkey%5B%22GlobalHotkeyManager.cs%3Cbr%2F%3EGlobal%20Hotkeys%22%5D%0AConfigMgr%5B%22ConfigProfileManager.cs%3Cbr%2F%3EConfiguration%20Profile%20Management%22%5D%0Aend%0Asubgraph%20%22UI%20Layer%22%0AToolbar%5B%22ToolbarRegistry.cs%3Cbr%2F%3EToolbar%20Registration%20and%20Layout%22%5D%0AAppRes%5B%22App.xaml%3Cbr%2F%3EResources%20and%20System%20Tray%20Menu%22%5D%0Aend%0Asubgraph%20%22Plugin%20Layer%22%0AIPlugin%5B%22IPlugin.cs%3Cbr%2F%3EPlugin%20Interface%22%5D%0AIHost%5B%22IPluginHost.cs%3Cbr%2F%3EPlugin%20Host%20Interface%22%5D%0APluginBase%5B%22PluginBase.cs%3Cbr%2F%3EPlugin%20Base%20Class%22%5D%0Aend%0AApp%20--%3E%20MainWindow%0AMainWindow%20--%3E%20Toolbar%0AMainWindow%20--%3E%20Log%0AMainWindow%20--%3E%20Noti%0AMainWindow%20--%3E%20Hotkey%0AApp%20--%3E%20Log%0AApp%20--%3E%20ExHandler%0AApp%20--%3E%20Telemetry%0AApp%20--%3E%20AppRes%0AIPlugin%20--%3E%20IHost%0APluginBase%20--%3E%20IPlugin%0APluginBase%20--%3E%20IHost%0A"})]),fallback:i(()=>e[0]||(e[0]=[a(" Loading... ")])),_:1})),e[6]||(e[6]=o('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>Application Entry &amp; Lifecycle Management: App.xaml.cs is responsible for application startup, command line argument parsing, watchdog monitoring, crash listening, exception handling, tray menus, and resource initialization.</li><li>Main Window &amp; View Model: MainWindow.xaml.cs hosts the UI logic, toolbar injection, notifications, timers, PPT/COM integration, global hotkeys, page and canvas management.</li><li>Logging &amp; Exceptions: LogHelper provides unified log writing and archiving; ExceptionHandler provides exception handling and continue-execution strategies.</li><li>Notification Center: NotificationCenterService provides message queuing, historical logs, and priority scheduling.</li><li>Telemetry &amp; Diagnostics: TelemetryUploader is responsible for anonymized telemetry data collection and reporting, as well as crash log and execution log gathering.</li><li>Configuration Management: ConfigProfileManager supports saving, switching, and hot-reloading multiple configuration profiles.</li><li>Toolbar System: ToolbarRegistry provides dynamic layout, rule-based display, and configuration persistence.</li><li>Global Hotkeys: GlobalHotkeyManager provides cross-screen, context-aware hotkey registration and management.</li><li>Plugin System: IPlugin/IPluginHost/PluginBase define plugin lifecycles and service registration contracts.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>InkCanvasForClass utilizes MVVM and modular layered architecture:</p><ul><li>View Layer (View): MainWindow and various windows/controls, responsible for rendering and user interaction.</li><li>ViewModel Layer (ViewModel): MainWindow undertakes a significant portion of ViewModel responsibilities (Hybrid MVVM), implementing data-driven logic through property change notifications and command bindings.</li><li>Service Layer (Service): Services such as logging, exceptions, notifications, telemetry, configuration, and hotkeys are provided as static classes or singletons.</li><li>Plugin Layer (Plugin): Implements functional extensibility and lifecycle management via IPlugin/IPluginHost abstractions.</li><li>Event-Driven: Global events (tray menu, system events, crash events), notification center events, and toolbar rule evaluations form a loosely coupled message flow.</li></ul>',5)),(n(),s(l,null,{default:i(()=>[t(r,{id:"mermaid-131",class:"mermaid",graph:"graph%20TB%0AView%5B%22View%20Layer%3Cbr%2F%3EMainWindow.xaml.cs%20etc.%22%5D%20--%3E%20VM%5B%22ViewModel%20Layer%3Cbr%2F%3EProperty%20Change%20and%20Command%20Binding%22%5D%0AVM%20--%3E%20Services%5B%22Service%20Layer%3Cbr%2F%3ELog%2FException%2FNotification%2FTelemetry%2FConfig%2FHotkey%22%5D%0AServices%20--%3E%20Plugins%5B%22Plugin%20Layer%3Cbr%2F%3EIPlugin%2FIPluginHost%22%5D%0AServices%20--%3E%20Events%5B%22Event%20Driven%3Cbr%2F%3ETray%2FSystem%2FCrash%2FNotification%22%5D%0AEvents%20--%3E%20View%0APlugins%20--%3E%20View%0A"})]),fallback:i(()=>e[1]||(e[1]=[a(" Loading... ")])),_:1})),e[7]||(e[7]=o('<p>[This diagram is a conceptual architectural representation and does not directly map to specific source code files]</p><h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="application-entry-and-startup-workflow-app-xaml-cs" tabindex="-1">Application Entry and Startup Workflow (App.xaml.cs) <a class="header-anchor" href="#application-entry-and-startup-workflow-app-xaml-cs" aria-label="Permalink to &quot;Application Entry and Startup Workflow (App.xaml.cs)&quot;">​</a></h3><ul><li>Startup Phase: Parse command line arguments, set AppUserModelID, initialize telemetry (Sentry), and configure TLS protocols to ensure compatibility with Windows 7.</li><li>Watchdog Monitoring: Recognize the --watchdog argument to launch the watchdog main loop; determine whether to start the watchdog based on crash behavior (silent restart).</li><li>Crash Listening: Register handlers for unhandled exceptions, console interrupts, system session endings, process exits, etc., uniformly writing crash logs and cleaning up resources.</li><li>Splash Screen: Conditionally load the splash screen, supporting progress and message updates.</li><li>Global Exception Handling: UI thread and non-UI thread exceptions are handled separately, with safe degradation for specific COM exceptions.</li></ul>',4)),(n(),s(l,null,{default:i(()=>[t(r,{id:"mermaid-168",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20OS%20as%20%22Operating%20System%22%0Aparticipant%20App%20as%20%22App.xaml.cs%22%0Aparticipant%20Watchdog%20as%20%22Watchdog%20Process%22%0Aparticipant%20Crash%20as%20%22Crash%20Listener%22%0Aparticipant%20Sentry%20as%20%22Telemetry(Sentry)%22%0AOS-%3E%3EApp%20%3A%20Start%20Process%0AApp-%3E%3EApp%20%3A%20Parse%20Command%20Line%20Arguments%0AApp-%3E%3EApp%20%3A%20Initialize%20Telemetry%20%2F%20Configure%20TLS%0AApp-%3E%3ECrash%20%3A%20Register%20Exception%20and%20Session%20Events%0AApp-%3E%3EApp%20%3A%20Determine%20Whether%20to%20Start%20Watchdog%0Aalt%20Watchdog%20Needed%0AApp-%3E%3EWatchdog%20%3A%20Start%20Watchdog%20Process%0Aend%0AApp-%3E%3ESentry%20%3A%20Initialize%20Telemetry%0AApp--%3E%3EOS%20%3A%20Enter%20Message%20Loop%0A"})]),fallback:i(()=>e[2]||(e[2]=[a(" Loading... ")])),_:1})),e[8]||(e[8]=o('<h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Component Coupling: <ul><li>MainWindow and ToolbarRegistry are tightly coupled (injection and layout), but coupling is reduced through the rule system.</li><li>App is tightly coupled with crash listening, tray menus, and telemetry, reflecting its global service nature.</li><li>The plugin system is loosely coupled via IPluginHost to prevent the core from directly depending on extensions.</li></ul></li><li>External Dependencies: <ul><li>Sentry is used for telemetry and crash reporting.</li><li>NHotkey is used for global hotkeys.</li><li>WPF/XAML resources and modern UI control libraries.</li></ul></li></ul>',2)),(n(),s(l,null,{default:i(()=>[t(r,{id:"mermaid-218",class:"mermaid",graph:"graph%20LR%0AApp%5B%22App.xaml.cs%22%5D%20--%3E%20Crash%5B%22Crash%20Listening%22%5D%0AApp%20--%3E%20Sentry%5B%22Sentry%20Telemetry%22%5D%0AApp%20--%3E%20Tray%5B%22Tray%20Menu%20(App.xaml)%22%5D%0AMainWindow%5B%22MainWindow.xaml.cs%22%5D%20--%3E%20Toolbar%5B%22ToolbarRegistry%22%5D%0AMainWindow%20--%3E%20Hotkey%5B%22GlobalHotkeyManager%22%5D%0AMainWindow%20--%3E%20Log%5B%22LogHelper%22%5D%0AMainWindow%20--%3E%20Noti%5B%22NotificationCenterService%22%5D%0APlugins%5B%22IPlugin%2FIPluginHost%22%5D%20--%3E%20MainWindow%0A"})]),fallback:i(()=>e[3]||(e[3]=[a(" Loading... ")])),_:1})),e[9]||(e[9]=o('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Startup Optimization: Splash screen and progress indicators reduce perceived waiting time; conditional loading and lazy initialization (e.g., log directories, configuration files).</li><li>Thread Model: UI events run on the Dispatcher to avoid cross-thread UI access; global hotkey callbacks are dispatched on the main thread.</li><li>I/O &amp; Disk: Writing logs and configuration files uses write-protected directory creation and atomic write strategies; log folder size limits and cleanup.</li><li>Exceptions &amp; Stability: Safe degradation for WPF InkCanvas known thread access issues; crash listening and watchdogs ensure availability.</li><li>Telemetry Overhead: Anonymized and asynchronous reporting avoids blocking the main thread.</li></ul><p>[This section provides general performance recommendations and does not directly analyze specific code snippets]</p><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Crash Log Location: Crash logs are located in the Crashes folder in the application root directory, named by startup time, containing system state information such as memory/CPU/running duration.</li><li>Log Viewing: LogHelper supports archiving by startup time or single file mode, featuring recursive logging protection and cleanup strategies.</li><li>Exception Handling: ExceptionHandler provides exception logging and continuation strategies, distinguishing between fatal exceptions (memory/access violation) and recoverable ones.</li><li>Watchdog: Watchdog processes are identified by the --watchdog parameter, terminating the main process if necessary to enter the monitoring loop.</li><li>Telemetry Diagnostics: TelemetryUploader collects crash and execution logs (anonymized) to facilitate remote diagnostics.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>InkCanvasForClass achieves a stable, extensible, and easy-to-maintain desktop application architecture through MVVM and modular layered design, combined with event-driven and global services. The application entry startup workflow, crash monitoring, and watchdog ensure availability; configuration management and toolbar systems offer flexible layout and policy control; the plugin system lays the groundwork for ecosystem expansion. It is recommended in future iterations to further clarify MVVM boundaries, introduce dependency injection containers to enhance service decoupling, and improve unit testing and observability metrics.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ul><li>Configuration File Locations: Configs/Settings.json (currently active), Configs/Profiles/* (multi-profile), Configs/HotkeyConfig.json (hotkey configuration), Configs/ToolbarConfigs/* (toolbar layout).</li><li>Resources &amp; Themes: App.xaml aggregates resource dictionaries and modern UI resources; tray menus and icon resources are managed centrally.</li><li>Runtime Configuration: App.config specifies the .NET runtime version and compatibility policies.</li></ul>',9))])}const w=g(m,[["render",h]]);export{E as __pageData,w as default};
